<script setup lang="ts">
import { Sensor } from '../../types/Sensor';

const props = defineProps<{
    selectedNavElementTitle: string,
    selectedSensor: Sensor | null,
    navElements: object[]
}>();

const emit = defineEmits<{
    (e: 'select-home'): void;
    (e: 'select-nav-element', navElement: object): void;
    (e: 'oneLevelBack'): void;
}>();
</script>

<template>
    <nav class="bg-gray text-white rounded-lg m-8 select-none">
        <ul class="flex gap-6 justify-end p-[30px]">
            <li class="bg-franconia w-[49px] h-[44px] rounded-lg flex items-center justify-center hover:cursor-pointer" @click="emit('select-home')">
                <img src="/icons/home.svg">
            </li>
            <li v-if="selectedNavElementTitle !== ''" @click="emit('oneLevelBack')" class="bg-white rounded-lg w-[49px] h-[44px] cursor-pointer">
                <img src="/icons/back_arrow.svg">
            </li>
            <li class="py-[10px] px-[15px] bg-vines rounded-lg hover:cursor-pointer text-title-sm flex items-center justify-center" :class="{'bg-white text-vines' : navElement.sensorId && navElement.sensorId === selectedSensor?.id}" v-for="navElement in props.navElements" :key="navElement.title" @click="emit('select-nav-element', navElement)">
                    {{ navElement.title }}
            </li>
        </ul>
    </nav>
</template>

<style scoped>

</style>
